import{_ as o,o as t,c as n,am as r}from"./chunks/framework._FJXuPhs.js";const u=JSON.parse('{"title":"SpringBoot学习_学习02","description":"","frontmatter":{"title":"SpringBoot学习_学习02","excerpt":"学习的路上，才知道路还很远，迷茫是未来的毒药。","date":"2024-05-01 10:49:20","updated":"2024-05-01 10:49:20"},"headers":[],"relativePath":"框架/框架 Spring家族/框架 SpringBoot/SpringBoot学习_学习02.md","filePath":"框架/框架 Spring家族/框架 SpringBoot/SpringBoot学习_学习02.md","lastUpdated":null}'),a={name:"框架/框架 Spring家族/框架 SpringBoot/SpringBoot学习_学习02.md"};function l(e,i,p,s,g,c){return t(),n("div",null,[...i[0]||(i[0]=[r('<p>参考： <a href="http://svip.iocoder.cn/Spring-Boot/Interview/" target="_blank" rel="noreferrer">http://svip.iocoder.cn/Spring-Boot/Interview/</a></p><p>看完这篇文章，感觉收效甚微，这里记录一下这套视频的相关笔记，同时如果后续进行回顾的话希望对于 SpringBoot 有更好的一个理解和具体使用。（后续打算将相关的框架集成相关实际项目使用的内容搞一下，根据这个项目： <a href="https://github.com/YunaiV/SpringBoot-Labs" target="_blank" rel="noreferrer">https://github.com/YunaiV/SpringBoot-Labs</a> ）</p><p>视频地址： <a href="https://www.bilibili.com/video/BV1Fh4y1D7Aq" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Fh4y1D7Aq</a></p><p>学习时间：2024-05-01 10:49:20</p><h4 id="springboot-自动配置原理" tabindex="-1">SpringBoot 自动配置原理 <a class="header-anchor" href="#springboot-自动配置原理" aria-label="Permalink to &quot;SpringBoot 自动配置原理&quot;">​</a></h4><ul><li>1、通过 @SpringBootConfiguration 引入了 @EnableAutoConfiguration(负责启动自动配置功能）</li><li>2、@EnableAutoConfiguration 引入了 @Import</li><li>3、Spring 容器启动时：加载loc容器时会解析@Import注解</li><li>4、@Import导入了一个deferredlmportSelector,它会使SpringBoot的自动配置类的顺序在最后，这样方便我们扩展和覆盖</li><li>5、然后读取所有的 /META-INF/spring.factories 文件 <ul><li>会去所有的 jar 包中和类路径中去读取这个文件（伪 SPI ）</li></ul></li><li>6、过滤出所有AutoConfigurtionClass类型的类</li><li>7、最后通过 @Condition 排除无效的自动配置类</li></ul><p>梅特 in For</p><p>看一下这段话：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240502113552.png" alt="image.png"></p><p>关于条件评估这步：</p><ul><li><code>@ConditionalOnClass</code>: 当类路径上存在指定的类时，相关的配置才会被应用。</li><li><code>@ConditionalOnBean</code>: 当上下文中存在指定的 Bean 时，相关的配置才会被应用。</li><li><code>@ConditionalOnProperty</code>: 当存在指定的配置属性且满足指定的值时，相关的配置才会被应用。</li></ul><h4 id="为什么-springboot-的-jar-可以直接运行" tabindex="-1">为什么 SpringBoot 的 jar 可以直接运行？ <a class="header-anchor" href="#为什么-springboot-的-jar-可以直接运行" aria-label="Permalink to &quot;为什么 SpringBoot 的 jar 可以直接运行？&quot;">​</a></h4><ul><li>1、SpringBoot提供了一个插件 spring-boot-maven-plugin, 用于把程序打包成一个可执行的jar包。</li><li>2、Spring Boot应用打包之后，生成一个Fat jar(jar包中包含jar),包含了应用依赖的 jar包和Spring Boot loader相关的类。</li><li>3、java -jar 会去找 jar中的 manifest文件，在那里面找到真正的启动类；</li><li>4、Fat jar的启动Main函数是 JarLauncher, 它负责创建一个LaunchedURLClassLoader:来加载boot-lib下面的jar,并以一个新线程启动应用的启动类的 Main函数（找到 manifest 中的 Start-Class）。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240503000739.png" alt="image.png"></p><hr><p>暂时没找到对应的类，而且 MainClass 对应相关配置也没看到，可能理解和实际有点问题。</p><h4 id="springboot-的启动原理" tabindex="-1">SpringBoot 的启动原理 <a class="header-anchor" href="#springboot-的启动原理" aria-label="Permalink to &quot;SpringBoot 的启动原理&quot;">​</a></h4><h4 id="springboot-的核心注解" tabindex="-1">SpringBoot 的核心注解 <a class="header-anchor" href="#springboot-的核心注解" aria-label="Permalink to &quot;SpringBoot 的核心注解&quot;">​</a></h4><ul><li>1、@SpringBootApplication注解：这个注解标识了一个SpringBoot.工程，它实际上是另外三个注解的组合，这三个注解是</li><li>2、@SpringBootConfiguration:这个注解实际就是一个@Configuration,表示启动类也是一个配置类</li><li>3、@EnableAutoConfiguration:向Spring容器中导入了一个Selector，用来加载 ClassPath 下 SpringFactoriest 中所定义的自动配置类，将这些自动加载为配置Bean。</li><li>4、@Conditional也很关键，如果没有它我们无法在自定义应用中进行定制开发 <ul><li>@ConditionalOnBean</li><li>@ConditionalOnClass</li><li>@ConditionalOnExpression</li></ul></li></ul>',19)])])}const h=o(a,[["render",l]]);export{u as __pageData,h as default};
